css:
.pb-ai-toggle-wrap,
.pb-ai-toggle-wrap * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: "Outfit", sans-serif;
}

.pb-ai-toggle-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.pb-ai-toggle {
  position: relative;
  width: 120px;
  height: 64px;
}

.pb-ai-toggle input {
  display: none;
}

.pb-ai-track {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 999px;
  cursor: pointer;
  overflow: hidden;
  isolation: isolate;

  background: linear-gradient(180deg, #2a2a35 0%, #1a1a24 45%, #111118 100%);

  box-shadow:
    0 0 0 6px rgba(255, 255, 255, 0.04),
    0 10px 30px rgba(0, 0, 0, 0.35),
    inset 0 2px 10px rgba(255, 255, 255, 0.08);

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.35s ease;
}

/* Gloss */
.pb-ai-track::before {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: inherit;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.22),
    rgba(255, 255, 255, 0.05) 45%,
    rgba(255, 255, 255, 0)
  );

  z-index: 1;
  pointer-events: none;
}

/* Grain texture */
.pb-ai-track::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;

  background-image: radial-gradient(
      circle at bottom center,
      rgba(255, 255, 255, 0.35) 0%,
      rgba(255, 255, 255, 0.12) 18%,
      rgba(255, 255, 255, 0.04) 35%,
      transparent 65%
    ),
    radial-gradient(rgba(255, 255, 255, 0.14) 0.8px, transparent 0.8px),
    radial-gradient(rgba(255, 255, 255, 0.08) 0.5px, transparent 0.5px),
    radial-gradient(rgba(0, 0, 0, 0.08) 0.7px, transparent 0.7px);

  background-size:
    100% 100%,
    4px 4px,
    7px 7px,
    5px 5px;

  background-position:
    center,
    0 0,
    2px 2px,
    1px 3px;

  opacity: 0.55;
  mix-blend-mode: overlay;

  z-index: 2;
  pointer-events: none;
}

.pb-ai-thumb {
  position: absolute;
  top: 7px;
  left: 7px;

  width: 50px;
  height: 50px;
  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.98),
    rgba(240, 240, 255, 0.92)
  );

  color: #8f8fa8;
  font-size: 18px;
  font-weight: 600;

  box-shadow:
    inset 0 2px 6px rgba(255, 255, 255, 0.9),
    inset 0 -4px 8px rgba(120, 120, 160, 0.12),
    0 8px 20px rgba(0, 0, 0, 0.25);

  transition:
    transform 0.35s cubic-bezier(0.65, 0.05, 0.36, 1),
    color 0.35s ease;

  z-index: 5;
}

.pb-ai-thumb span {
  transform: translateY(-1px);
}

/* ON STATE */
.pb-ai-toggle input:checked + .pb-ai-track {
  background: linear-gradient(180deg, #a67dff 0%, #7a45ff 45%, #5d24ff 100%);

  box-shadow:
    0 0 0 6px rgba(125, 71, 255, 0.12),
    0 10px 30px rgba(98, 43, 255, 0.35),
    inset 0 2px 10px rgba(255, 255, 255, 0.22);
}

.pb-ai-toggle input:checked + .pb-ai-track .pb-ai-thumb {
  transform: translateX(56px);
  color: #7a45ff;
}

/* Hover */
.pb-ai-track:hover {
  transform: translateY(-2px) scale(1.02);
}

/* Active */
.pb-ai-track:active {
  transform: scale(0.98);
}
